export const SOCIAL_CAPTION_PROMPT = "Write a social media caption and hashtags for a short video. Language: {{language_name}}. Platform: {{platform}}. Video summary: {{summary}} (title texts, caption transcript excerpt, duration). Output JSON: {\"caption\": string (≤ 2200 chars, first line is a hook ≤ 80 chars, no emojis unless the summary contains them), \"hashtags\": string[] (8–15, lowercase, no spaces, mix of 3 broad, 7 niche, 2 branded if a brand is given)}. Do not invent facts not in the summary.";
